    ["Move down"] = "W dół",
    ["Delete rule {n}"] = "Usuń zasadę {n}",
    ["Other versions of this rule"] = "Inne wersje tej zasady",
    ["Leave a version empty to use the rule text."] = "Zostaw wersję pustą, aby użyć tekstu zasady.",
    ["For a speaker with a reply length of its own"] = "Dla mówcy z własną długością odpowiedzi",
    ["For Mature content"] = "Dla treści dla dorosłych",
    ["Shipped: off"] = "Oryginał: wył.",
    ["Shipped: the mod’s own limit"] = "Oryginał: limit samego moda",
